// Общее для шага 1 /addbusiness — место бизнеса за границей (#75ae6c, specs/addbusiness-overseas-location.md).
// ПРОД, ничего не пишем: GET/HEAD/OPTIONS и продление сессии (POST auth/v1/token) пропускаются, всё прочее
// (в т. ч. POST rest/v1/business — создание черновика) обрывается и запоминается в ctl.writes — в конце теста должно быть пусто.
import { expect, BrowserContext, Page } from '@playwright/test';

export const LOAD = { timeout: 25_000 };
export const NEXT = 'שלב הבא';
export const ABROAD_TYPE = 'עסקים בחו"ל';
export const SALE_TYPE = 'עסקים למסירה - מכירה';
export const ABROAD_CATEGORY = 'חו"ל';
export const HALLS_CATEGORY = 'אולמות אירועים';
export const ABROAD_PLACEHOLDER = 'מיקום העסק בחו"ל*';
export const ADDRESS_PLACEHOLDER = 'כתובת (רחוב ומספר בית)';
export const CITY_BUTTON = 'פתח רשימת ערים';
export const REQUIRED_TOAST = /אנא מלא את כל השדות החובה/;
export const STEP2_MARK = 'משך פעילות העסק (שנים/חודשים)';
export const ABROAD_TEXT = 'QA-AUTO ברלין, גרמניה';

const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

export type Ctl = { writes: string[] };

/** До первого перехода: только чтение, cookie «חיוניים בלבד», окно PWA снято, локальный черновик мастера очищен. */
export async function prepare(context: BrowserContext): Promise<Ctl> {
  const ctl: Ctl = { writes: [] };
  await context.route('**/*', (route) => {
    const req = route.request();
    const m = req.method();
    if (SAFE_METHODS.includes(m) || (m === 'POST' && /\/auth\/v1\/token/.test(req.url()))) return route.fallback();
    ctl.writes.push(`${m} ${req.url()}`);
    return route.abort('blockedbyclient');
  });
  await context.addInitScript(() => {
    try {
      localStorage.setItem(
        'cookie-consent-v2',
        JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
      );
      localStorage.setItem('b4s_install_prompt_dismissed_at', String(Date.now()));
      for (const k of Object.keys(localStorage)) if (k.startsWith('biz4sale:addBusinessDraft:')) localStorage.removeItem(k);
    } catch {}
  });
  return ctl;
}

export async function openWizard(page: Page) {
  await page.goto('/addbusiness');
  await expect(page.getByRole('button', { name: NEXT }), 'шаг 1 мастера').toBeVisible(LOAD);
  await expect(page.getByRole('combobox').filter({ hasText: 'סוג מודעה' }), 'סוג מודעה по умолчанию пуст').toBeVisible(LOAD);
}

/** Выбрать значение в комбобоксе, у которого сейчас виден текст current. */
export async function pick(page: Page, current: string, option: string) {
  await page.getByRole('combobox').filter({ hasText: current }).first().click();
  await page.getByRole('option', { name: option, exact: true }).click();
  await expect(page.getByRole('combobox').filter({ hasText: option }).first()).toBeVisible();
}

export const abroadField = (page: Page) => page.getByPlaceholder(ABROAD_PLACEHOLDER, { exact: true });
export const cityButton = (page: Page) => page.getByRole('button', { name: CITY_BUTTON });
export const addressField = (page: Page) => page.getByPlaceholder(ADDRESS_PLACEHOLDER, { exact: true });
export const regionCombo = (page: Page) => page.getByRole('combobox').filter({ hasText: /^אזור$/ });

/** Свободное поле места видно; выбора города/адреса/района нет. */
export async function expectAbroadMode(page: Page) {
  await expect(abroadField(page), 'поле «מיקום העסק בחו"ל*»').toBeVisible();
  expect(await abroadField(page).evaluate((e) => e.tagName), 'поле многострочное').toBe('TEXTAREA');
  await expect(cityButton(page), 'нет «פתח רשימת ערים»').toHaveCount(0);
  await expect(addressField(page), 'нет «כתובת (רחוב ומספר בית)»').toHaveCount(0);
  await expect(regionCombo(page), 'нет списка «אזור»').toHaveCount(0);
}

/** Обычный режим: город/адрес/район есть, свободного поля нет. */
export async function expectCityMode(page: Page) {
  await expect(cityButton(page), '«פתח רשימת ערים»').toBeVisible();
  await expect(addressField(page), '«כתובת (רחוב ומספר בית)»').toBeVisible();
  await expect(regionCombo(page), 'список «אזור»').toBeVisible();
  await expect(abroadField(page), 'нет «מיקום העסק בחו"ל*»').toHaveCount(0);
}

export function expectNoWrites(ctl: Ctl) {
  expect(ctl.writes, 'ни одного запроса записи (черновик не создавался)').toEqual([]);
}
